"""Write two small synthetic songs (generated by code, no real audio) for the Playwright smoke."""

import sys
from pathlib import Path

from mixconsole.io import write_audio
from mixconsole.testing.synth import generate_track

out = Path(sys.argv[1])
out.mkdir(parents=True, exist_ok=True)
a, _ = generate_track(bpm=120, bars=32, vocal_bars=(8, 9, 10, 11), breakdown_bars=(16, 17), seed=11)
b, _ = generate_track(bpm=124, bars=32, vocal_bars=(12, 13), seed=22)
write_audio(out / "synthetic-a.wav", a)
write_audio(out / "synthetic-b.wav", b)
sys.stdout.write(f"{out}\n")
